package net.hollowcube.mapmaker.runtime.parkour.action.impl;

import net.minestom.server.sound.SoundEvent;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

/// Longest variant length of each vanilla sound event, generated by `./gradlew :bin:packer:generateSoundDurations`.
public final class SoundDurations {
    private static final Map<String, Integer> DURATIONS = load();

    /// @return the duration in ms at the given pitch, or -1 if unknown (eg a sound newer than the table)
    public static int durationMs(SoundEvent event, float pitch) {
        var duration = DURATIONS.get(event.key().value());
        if (duration == null) return -1;
        // The client clamps pitch to [0.5, 2] in SoundEngine#calculatePitch.
        return (int) (duration / Math.clamp(pitch, 0.5f, 2f));
    }

    private static Map<String, Integer> load() {
        var durations = new HashMap<String, Integer>();
        try (var is = Objects.requireNonNull(SoundDurations.class.getResourceAsStream("/sound_durations.txt"));
             var reader = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                int space = line.indexOf(' ');
                if (space == -1) continue;
                durations.put(line.substring(0, space), Integer.parseInt(line.substring(space + 1)));
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return durations;
    }

    private SoundDurations() {
    }
}
